using System.Net; using FluentValidation; namespace Kaits.WebApi.Middlewares; public class ErrorHandlingMiddleware{ private readonly RequestDelegate _next; private readonly ILogger<ErrorHandlingMiddleware> _logger; public ErrorHandlingMiddleware(RequestDelegate next, ILogger<ErrorHandlingMiddleware> logger){ _next=next; _logger=logger;} public async System.Threading.Tasks.Task Invoke(HttpContext context){ try{ await _next(context);} catch(ValidationException ex){ _logger.LogWarning(ex,"Validation error"); context.Response.StatusCode=(int)HttpStatusCode.BadRequest; await context.Response.WriteAsJsonAsync(new { error="Validation failed", details=ex.Errors.Select(e=> new { e.PropertyName, e.ErrorMessage })}); } catch(System.Exception ex){ _logger.LogError(ex,"Unhandled error"); context.Response.StatusCode=(int)HttpStatusCode.InternalServerError; await context.Response.WriteAsJsonAsync(new { error="Internal server error"}); } } }